class Todo {
  private nextId = 1;
  private todos = [];

  constructor(data: { text: string; completed: boolean } = {}) {
    this.todos.push({ id: this.nextId, text: data.text, completed: !!data.completed });
    this.nextId++;
  }

  addTodo(text: string): Todo {
    return new Todo({ text });
  }

  getTodo(id: number): { id: number; text: string; completed: boolean } | undefined {
    const todo = this.todos.find((todo) => todo.id === id);
    if (todo) return todo;
    return undefined;
  }

  toggleTodo(id: number): void {
    const index = this.todos.findIndex((todo) => todo.id === id);
    if (index !== -1) {
      this.todos[index].completed = !this.todos[index].completed;
    }
  }

  deleteTodo(id: number): void {
    const index = this.todos.findIndex((todo) => todo.id === id);
    if (index !== -1) {
      this.todos.splice(index, 1);
      this.nextId--;
    }
  }

  listTodos(): { id: number; text: string; completed: boolean }[] {
    return this.todos;
  }

  listCompleted(): { id: number; text: string; completed: boolean }[] {
    return this.todos.filter((todo) => todo.completed);
  }

  listPending(): { id: number; text: string; completed: boolean }[] {
    return this.todos.filter((todo) => !todo.completed);
  }

  clearCompleted(): void {
    const todos = [...this.todos];
    for (const todo of todos) {
      if (todo.completed) {
        this.deleteTodo(todo.id);
      }
    }
    this.todos = todos;
  }
}

export function createTodoApp(): Todo {
  return new Todo();
}
