            if (todo) {
                todo.completed = !todo.completed;
            }
        },
        deleteTodo(id: number): boolean {
            return todos.delete(id);
        },
        listTodos(): Todo[] {
            return Array.from(todos.values());
        },
        listCompleted(): Todo[] {
            const result: Todo[] = [];
            for (const todo of todos.values()) {
                if (todo.completed) {
                    result.push(todo);
                }
            }
            return result;
        },
        listPending(): Todo[] {
            const result: Todo[] = [];
            for (const todo of todos.values()) {
                if (!todo.completed) {
                    result.push(todo);
                }
            }
            return result;
        },
        clearCompleted(): void {
            for (const [id, todo] of todos.entries()) {
                if (todo.completed) {
                    todos.delete(id);
                }
            }
        },
    };
}

