export function createCalculator(): any {
  // ---- internal state --------------------------------------------------
  let value: number = 0;
  let memory: number | undefined = undefined;

  // ---- operations -------------------------------------------------------
  const add = (n: number): unknown => { value += n; return this } as unknown;
  const subtract = (n: number): unknown => { value -= n; return this } as unknown;
  const multiply = (n: number): unknown => { value *= n; return this } as unknown;
  const divide = (n: number): unknown =>
    n === 0 ? ((value as any) = NaN) : ((value as any) /= n),
    ;
  const clear = (): unknown => { value = 0; return this } as unknown;
  const result = (): number | undefined => value;

  // memory state helpers
  const memoryStore = (): void => {
    if (memory === undefined) memory = value;
    else memory = value;
  };
  const memoryRecall = (): number | undefined => memory;
  const memoryReset = (): void => { memory = undefined; return this } as unknown;
  const memoryAdd = (): unknown => {
    if (memory !== undefined) {
      value += memory;
    }
    return this;
  };

  // ---- build the public object -----------------------------------------
  const calc: any = {
    add,
    subtract,
    multiply,
    divide,
    clear,
    result,
    memoryStore,
    memoryRecall,
    memoryReset,
    memoryAdd,
  } as unknown as any;

  return calc;
}
```

