interface Calculator {
  add(n: number): Calculator;
  subtract(n: number): Calculator;
  multiply(n: number): Calculator;
  divide(n: number): Calculator;
  clear(): Calculator;
  result(): number;
  memoryStore(): Calculator;
  memoryRecall(): number;
  memoryClear(): Calculator;
  memoryAdd(): Calculator;
}

class CalculatorImpl implements Calculator {
  private currentValue: number = 0;
  private memoryValue: number = 0;

  add(n: number): Calculator {
    this.currentValue += n;
    return this;
  }

  subtract(n: number): Calculator {
    this.currentValue -= n;
    return this;
  }

  multiply(n: number): Calculator {
    this.currentValue *= n;
    return this;
  }

  divide(n: number): Calculator {
    if (n === 0) throw new Error("Cannot divide by zero");
    this.currentValue /= n;
    return this;
  }

  clear(): Calculator {
    this.currentValue = 0;
    return this;
  }

  result(): number {
    return this.currentValue;
  }

  memoryStore(): Calculator {
    this.memoryValue = this.currentValue;
    return this;
  }

  memoryRecall(): number {
    return this.memoryValue;
  }

  memoryClear(): Calculator {
    this.memoryValue = 0;
    return this;
  }

  memoryAdd(): Calculator {
    this.memoryValue += this.currentValue;
    return this;
  }
}

export function createCalculator(): Calculator {
  return new CalculatorImpl();
}
